import { useEffect, useState } from "react";

export default function AdminGallery() {
  const [images, setImages] = useState([]);
  const [success, setSuccess] = useState("");
  const [loading, setLoading] = useState(false);

  const fetchImages = async () => {
    const res = await fetch("http://localhost:5001/admin/gallery", {
      headers: {
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
    });
    const data = await res.json();
    setImages(data.reverse()); // newest first
  };

  useEffect(() => {
    fetchImages();
  }, []);

  const upload = async (e) => {
    if (!e.target.files[0]) return;

    setLoading(true);
    setSuccess("");

    const form = new FormData();
    form.append("image", e.target.files[0]);

    await fetch("http://localhost:5001/admin/gallery", {
      method: "POST",
      headers: {
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
      body: form,
    });

    await fetchImages();

    setLoading(false);
    setSuccess("Image uploaded successfully ✔️");

    setTimeout(() => setSuccess(""), 3000);
  };

  const remove = async (id) => {
    await fetch(`http://localhost:5001/admin/gallery/${id}`, {
      method: "DELETE",
      headers: {
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
    });

    fetchImages();
  };

  return (
    <div>
      {/* HEADER */}
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-3xl font-bold text-yellow-400">
          Gallery Manager
        </h2>

        <label className="cursor-pointer bg-yellow-400 text-black px-6 py-3 rounded-lg font-semibold hover:bg-yellow-300 transition">
          {loading ? "Uploading..." : "Upload Image"}
          <input
            type="file"
            onChange={upload}
            hidden
          />
        </label>
      </div>

      {/* SUCCESS MESSAGE */}
      {success && (
        <div className="mb-6 p-4 rounded-lg bg-green-500/10 border border-green-500 text-green-400">
          {success}
        </div>
      )}

      {/* EMPTY STATE */}
      {images.length === 0 && (
        <p className="text-gray-400 text-center mt-20">
          No images uploaded yet
        </p>
      )}

      {/* GALLERY GRID */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
        {images.map((img, index) => (
          <div
            key={img._id}
            className={`relative rounded-xl overflow-hidden border ${
              index === 0
                ? "border-yellow-400"
                : "border-white/10"
            }`}
          >
            {/* IMAGE */}
            <img
              src={`http://localhost:5001/uploads/${img.filename}`}
              alt=""
              className="w-full h-44 object-cover"
            />

            {/* NEW TAG */}
            {index === 0 && (
              <span className="absolute top-2 left-2 bg-yellow-400 text-black text-xs px-3 py-1 rounded-full font-bold">
                NEW
              </span>
            )}

            {/* DELETE */}
            <button
              onClick={() => remove(img._id)}
              className="absolute bottom-2 right-2 bg-red-600 px-3 py-1 text-sm rounded hover:bg-red-500 transition"
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
